// Generate sample schedule data
var scheduleData = {
    LineData1: {
        LineType: 0, // Empty line
        ScheduleListKeyID: null
    },
    LineData2: {
        LineType: 1, // Order line
        ScheduleListKeyID: 1001,
        OrderNo: "ORD-2024-001",
        OrderKeyID: 1001,
        OrderDate: "2024-01-15"
    },
    LineData3: {
        LineType: 2, // List line
        ScheduleListKeyID: 2001,
        ProductCode: "PROD-A001",
        Length: "1200mm",
        Qty: 50,
        DoneQty: 25,
        LineStatus: "In Progress"
    },
    LineData4: {
        LineType: 2, // List line
        ScheduleListKeyID: 2002,
        ProductCode: "PROD-B002",
        Length: "800mm",
        Qty: 30,
        DoneQty: 30,
        LineStatus: "Completed"
    },
    LineData5: {
        LineType: 2, // List line
        ScheduleListKeyID: 2003,
        ProductCode: "PROD-C003",
        Length: "1500mm",
        Qty: 20,
        DoneQty: 0,
        LineStatus: "Pending"
    },
    LineData6: {
        LineType: 3, // End of list
        ScheduleListKeyID: null
    }
};

// Generate machine status data
var machineData = {
    machines: [
        {
            id: "M001",
            name: "Machine 1",
            status: "running",
            statusText: "Running",
            currentJob: "PROD-A001",
            progress: 75,
            uptime: "2h 30m"
        },
        {
            id: "M002",
            name: "Machine 2",
            status: "stopped",
            statusText: "Stopped",
            currentJob: null,
            progress: 0,
            uptime: "0h 0m"
        },
        {
            id: "M003",
            name: "Machine 3",
            status: "paused",
            statusText: "Paused",
            currentJob: "PROD-C003",
            progress: 45,
            uptime: "1h 15m"
        }
    ]
};

// Generate status summary
var statusSummary = {
    totalOrders: 3,
    inProgress: 1,
    completed: 1,
    pending: 1
};

// Prepare message
msg.payload = {
    ...scheduleData,
    ...machineData,
    statusSummary: statusSummary,
    timestamp: new Date().toISOString()
};

msg.topic = "schedule/update";

return msg;

// Process actions from schedule list
var action = msg.payload;

// Log the action
node.log(`Schedule Action: ${action.action} on line ${action.lineKey}`);

// Add to history
var historyEntry = {
    type: 'info',
    message: `Action: ${action.action}`,
    details: `Line: ${action.lineKey}, KeyID: ${action.keyID}`,
    timestamp: new Date().toISOString()
};

// Store in global context
var history = global.get('scheduleHistory') || [];
history.unshift(historyEntry);
if (history.length > 100) {
    history = history.slice(0, 100);
}
global.set('scheduleHistory', history);

// Process specific actions
switch (action.action) {
    case 'editorder':
    case 'edit':
        msg.payload = {
            success: true,
            message: 'Edit action processed',
            action: action.action,
            lineKey: action.lineKey,
            keyID: action.keyID
        };
        break;

    case 'deleteorder':
    case 'delete':
        msg.payload = {
            success: true,
            message: 'Delete action processed',
            action: action.action,
            lineKey: action.lineKey,
            keyID: action.keyID
        };
        break;

    case 'markdone':
        msg.payload = {
            success: true,
            message: 'Mark done action processed',
            action: action.action,
            lineKey: action.lineKey,
            keyID: action.keyID
        };
        break;

    case 'run':
    case 'RunOrder':
        msg.payload = {
            success: true,
            message: 'Run action processed',
            action: action.action,
            lineKey: action.lineKey,
            keyID: action.keyID
        };
        break;

    default:
        msg.payload = {
            success: false,
            message: 'Unknown action',
            action: action.action
        };
}

msg.topic = `schedule/action/${action.action}`;

return msg;

// Process control panel actions
var action = msg.payload;

// Log the action
node.log(`Control Action: ${action.action}`);

// Add to history
var historyEntry = {
    type: 'info',
    message: `Control: ${action.action}`,
    details: `Action performed from control panel`,
    timestamp: new Date().toISOString()
};

// Store in global context
var history = global.get('scheduleHistory') || [];
history.unshift(historyEntry);
if (history.length > 100) {
    history = history.slice(0, 100);
}
global.set('scheduleHistory', history);

// Process specific control actions
switch (action.action) {
    case 'refresh':
        msg.payload = {
            success: true,
            message: 'Schedule refreshed',
            action: action.action
        };
        break;

    case 'add-new':
        msg.payload = {
            success: true,
            message: 'Add new item dialog opened',
            action: action.action
        };
        break;

    case 'pause-all':
        msg.payload = {
            success: true,
            message: 'All operations paused',
            action: action.action
        };
        break;

    case 'emergency-stop':
        msg.payload = {
            success: true,
            message: 'Emergency stop activated',
            action: action.action
        };
        historyEntry.type = 'error';
        break;

    default:
        msg.payload = {
            success: false,
            message: 'Unknown control action',
            action: action.action
        };
}

msg.topic = `control/action/${action.action}`;

return msg;

// Process machine control actions
var action = msg.payload;

// Log the action
node.log(`Machine Action: ${action.action} on machine ${action.machineId}`);

// Add to history
var historyEntry = {
    type: 'info',
    message: `Machine ${action.machineId}: ${action.action}`,
    details: `Machine control action performed`,
    timestamp: new Date().toISOString()
};

// Store in global context
var history = global.get('scheduleHistory') || [];
history.unshift(historyEntry);
if (history.length > 100) {
    history = history.slice(0, 100);
}
global.set('scheduleHistory', history);

// Process specific machine actions
switch (action.action) {
    case 'start':
        msg.payload = {
            success: true,
            message: `Machine ${action.machineId} started`,
            action: action.action,
            machineId: action.machineId
        };
        break;

    case 'stop':
        msg.payload = {
            success: true,
            message: `Machine ${action.machineId} stopped`,
            action: action.action,
            machineId: action.machineId
        };
        break;

    case 'pause':
        msg.payload = {
            success: true,
            message: `Machine ${action.machineId} paused`,
            action: action.action,
            machineId: action.machineId
        };
        break;

    case 'resume':
        msg.payload = {
            success: true,
            message: `Machine ${action.machineId} resumed`,
            action: action.action,
            machineId: action.machineId
        };
        break;

    default:
        msg.payload = {
            success: false,
            message: 'Unknown machine action',
            action: action.action
        };
}

msg.topic = `machine/action/${action.action}`;

return msg;

// Process history panel actions
var action = msg.payload;

// Log the action
node.log(`History Action: ${action.action}`);

// Process specific history actions
switch (action.action) {
    case 'filter':
        msg.payload = {
            success: true,
            message: `History filtered by: ${action.filter}`,
            action: action.action,
            filter: action.filter
        };
        break;

    case 'clear':
        // Clear history
        global.set('scheduleHistory', []);
        msg.payload = {
            success: true,
            message: 'History cleared',
            action: action.action
        };
        break;

    default:
        msg.payload = {
            success: false,
            message: 'Unknown history action',
            action: action.action
        };
}

msg.topic = `history/action/${action.action}`;

return msg;
